"""Controlled drift injection with known ground truth (the "dataset generated by transformation").

Drift taxonomy (Gama et al., 2014; Moreno-Torres et al., 2012). With a joint P_t(x, y) = P_t(x) P_t(y|x):

* ``none``      stationary control stream — used to measure false-alarm rates.
* ``covariate`` *virtual* drift: P(x) moves to a region not covered by training data, P(y|x) unchanged.
                Implemented by **selection bias** on real records (a new customer segment appears), so
                labels stay genuine.
* ``sensor``    feature corruption: chosen features are shifted by ``delta`` standard deviations
                (a sensor calibration fault / a changed upstream pipeline). P(x) changes *and* the observed
                relation to y changes -> mixed drift.
* ``real``      *real* concept drift: P(y|x) changes in a sub-region (labels flip with prob. rho), P(x)
                untouched. Theory predicts that no label-free signal computed from x alone can see it.

Every drift ramps in linearly: p(t) = clip((t - t0) / width, 0, 1); width=0 gives an abrupt drift.
The features that drift are recorded (``gt_features``) so XAI attributions can be scored against them.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional

import numpy as np
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

from . import data as D

DRIFT_TYPES = ["none", "covariate", "sensor", "real"]


@dataclass
class StreamData:
    X_train: np.ndarray
    y_train: np.ndarray
    X_cal: np.ndarray
    y_cal: np.ndarray
    X_stream: np.ndarray
    y_stream: np.ndarray
    t0: Optional[int]
    width: int
    drift_type: str
    p: np.ndarray                      # drift intensity in [0,1] for every stream position
    gt_features: list = field(default_factory=list)
    feature_names: list = field(default_factory=list)
    n_classes: int = 2
    name: str = ""
    info: dict = field(default_factory=dict)


def ramp(L: int, t0: Optional[int], width: int) -> np.ndarray:
    if t0 is None:
        return np.zeros(L)
    t = np.arange(L)
    if width <= 0:
        return (t >= t0).astype(float)
    return np.clip((t - t0) / width, 0.0, 1.0)


def informative_features(X, y, candidates, rng, n_top=4, k=2, max_n=5000):
    """Pick k drift features at random among the n_top most informative continuous features (MI)."""
    if len(candidates) == 0:
        candidates = list(range(X.shape[1]))
    idx = rng.choice(len(X), size=min(max_n, len(X)), replace=False)
    mi = mutual_info_classif(X[idx][:, candidates], y[idx], random_state=int(rng.integers(1 << 31)))
    top = [candidates[i] for i in np.argsort(mi)[::-1][:n_top]]
    return sorted(rng.choice(top, size=min(k, len(top)), replace=False).tolist())


def _take(pool, n, rng):
    return rng.choice(pool, size=n, replace=len(pool) < n)


def build_stream(tab: D.Tabular, drift_type: str, seed: int, cfg: dict) -> StreamData:
    """Turn a static tabular dataset into a train / calibration / stream split with injected drift."""
    rng = np.random.default_rng(seed)
    n_train, n_cal, L = cfg["n_train"], cfg["n_cal"], cfg["stream_len"]
    t0, width = cfg["t0"], cfg["width"]
    X, y = tab.X, tab.y
    N = len(X)

    # ---- natural stream: keep the time order, no injected drift, no ground-truth onset
    if tab.natural_order:
        L_nat = min(cfg.get("natural_len", 15000), N - n_train - n_cal)
        sl = slice(n_train + n_cal, n_train + n_cal + L_nat)
        Xtr, ytr = X[:n_train], y[:n_train]
        Xc, yc = X[n_train:n_train + n_cal], y[n_train:n_train + n_cal]
        Xs, ys = X[sl], y[sl]
        sc = StandardScaler().fit(Xtr)
        return StreamData(sc.transform(Xtr), ytr, sc.transform(Xc), yc, sc.transform(Xs), ys,
                          None, 0, "natural", np.zeros(len(Xs)), [], tab.feature_names, tab.n_classes,
                          tab.name, {"scaler_mean": sc.mean_.tolist()})

    p = ramp(L, None if drift_type == "none" else t0, width)
    gt = informative_features(X, y, tab.numeric_idx, rng, k=cfg.get("n_drift_features", 2))
    info = {}

    if drift_type == "covariate":
        z = (X[:, gt] - X[:, gt].mean(0)) / (X[:, gt].std(0) + 1e-12)
        s = z.mean(1)
        q = np.quantile(s, cfg.get("region_q", 0.75))
        inside = rng.permutation(np.where(s <= q)[0])
        novel = rng.permutation(np.where(s > q)[0])
        tr, ca, pool_in = inside[:n_train], inside[n_train:n_train + n_cal], inside[n_train + n_cal:]
        from_novel = rng.random(L) < p
        idx = np.empty(L, int)
        idx[~from_novel] = _take(pool_in, int((~from_novel).sum()), rng)
        idx[from_novel] = _take(novel, int(from_novel.sum()), rng)
        Xs, ys = X[idx].copy(), y[idx].copy()
        info["region_threshold"] = float(q)
    else:
        perm = rng.permutation(N)
        tr, ca, pool = perm[:n_train], perm[n_train:n_train + n_cal], perm[n_train + n_cal:]
        idx = _take(pool, L, rng)
        Xs, ys = X[idx].copy(), y[idx].copy()
        if drift_type == "sensor":
            sd = X[tr][:, gt].std(0)
            Xs[:, gt] += (p[:, None] * cfg.get("sensor_delta", 2.0)) * sd[None, :]
        elif drift_type == "real":
            g = gt[0]
            gt = [g]
            med = np.median(X[tr][:, g])
            region = Xs[:, g] > med
            if region.mean() < 0.35:          # heavily tied ordinal feature (e.g. PAY_x): include the median
                region = Xs[:, g] >= med
            flip = region & (rng.random(L) < p * cfg.get("flip_rho", 0.7))
            ys[flip] = (ys[flip] + 1) % tab.n_classes
            info["flipped_fraction_post"] = float(flip[p >= 1].mean()) if (p >= 1).any() else 0.0
        elif drift_type != "none":
            raise ValueError(drift_type)

    if drift_type == "none":
        gt = []
    Xtr, ytr, Xc, yc = X[tr], y[tr], X[ca], y[ca]
    sc = StandardScaler().fit(Xtr)
    return StreamData(sc.transform(Xtr), ytr, sc.transform(Xc), yc, sc.transform(Xs), ys,
                      None if drift_type == "none" else t0, width, drift_type, p, gt,
                      tab.feature_names, tab.n_classes, tab.name, info)


def build_digits_stream(seed: int, cfg: dict, drift_type: str = "covariate") -> StreamData:
    """MNIST-like covariate drift: images rotate progressively by up to ``max_angle`` degrees."""
    tab = D.load_digits_tab()
    rng = np.random.default_rng(seed)
    n_train, n_cal, L = 900, 300, cfg["stream_len"]
    perm = rng.permutation(len(tab.X))
    tr, ca, pool = perm[:n_train], perm[n_train:n_train + n_cal], perm[n_train + n_cal:]
    idx = rng.choice(pool, size=L, replace=True)
    Xs, ys = tab.X[idx].copy(), tab.y[idx].copy()
    t0 = None if drift_type == "none" else cfg["t0"]
    p = ramp(L, t0, cfg["width"])
    if drift_type == "covariate":
        angles = p * cfg.get("max_angle", 40.0) * rng.choice([-1, 1], size=L)
        Xs = D.rotate_digits(Xs, angles)
    elif drift_type != "none":
        raise ValueError("digits supports none/covariate")
    sc = StandardScaler().fit(tab.X[tr])
    return StreamData(sc.transform(tab.X[tr]), tab.y[tr], sc.transform(tab.X[ca]), tab.y[ca],
                      sc.transform(Xs), ys, t0, cfg["width"], drift_type, p, [], tab.feature_names, 10,
                      "digits", {})


def build_sea_stream(seed: int, cfg: dict, drift_type: str = "real") -> StreamData:
    """SEA: the classic *real* concept drift benchmark (threshold on x1+x2 changes, P(x) fixed)."""
    L, t0, w = cfg["stream_len"], cfg["t0"], cfg["width"]
    Xtr, ytr = D.sea_stream(cfg["n_train"], 0, 0, 0, 1, seed + 100)
    Xc, yc = D.sea_stream(cfg["n_cal"], 0, 0, 0, 1, seed + 200)
    if drift_type == "real":
        Xs, ys = D.sea_stream(L, 0, 3, t0 + w // 2, w, seed)   # River centres the sigmoid at `position`
    elif drift_type == "none":
        Xs, ys = D.sea_stream(L, 0, 0, 0, 1, seed)
    else:
        raise ValueError("sea supports none/real")
    sc = StandardScaler().fit(Xtr)
    p = ramp(L, None if drift_type == "none" else t0, w)
    return StreamData(sc.transform(Xtr), ytr, sc.transform(Xc), yc, sc.transform(Xs), ys,
                      None if drift_type == "none" else t0, w, drift_type, p, [] if drift_type == "none" else [0, 1],
                      ["x1", "x2", "x3"], 2, "sea", {})


def make_stream(dataset: str, drift_type: str, seed: int, cfg: dict, tab: Optional[D.Tabular] = None) -> StreamData:
    if dataset == "digits":
        return build_digits_stream(seed, cfg, drift_type)
    if dataset == "sea":
        return build_sea_stream(seed, cfg, drift_type)
    if tab is None:
        tab = D.load_dataset(dataset)
    return build_stream(tab, drift_type, seed, cfg)
